# --- congruence (one per constructor) ----------------------------------------
def ADD_CONG(a, b):   return Thm(Add(a.l, b.l), Add(a.r, b.r), "add_cong",  _hyps(a, b))
def SUB_CONG(a, b):   return Thm(Sub(a.l, b.l), Sub(a.r, b.r), "sub_cong",  _hyps(a, b))
def SUM_CONG(a):      return Thm(Sum(a.l),      Sum(a.r),      "sum_cong",  _hyps(a))
def ELEM_CONG(a, b):  return Thm(Elem(a.l, b.l),Elem(a.r, b.r),"elem_cong", _hyps(a, b))
def CONS_CONG(a, b):  return Thm(Cons(a.l, b.l),Cons(a.r, b.r),"cons_cong", _hyps(a, b))

# --- definitional unfolding ---------------------------------------------------
def DEF_SUM_NIL():            return Thm(Sum(Nil()), Zero(), "def_sum_nil")
def DEF_SUM_CONS(x, xs):      return Thm(Sum(Cons(x, xs)), Add(x, Sum(xs)), "def_sum_cons")
def DEF_ELEM_NIL():           return Thm(Elem(Nil(), Nil()), Nil(), "def_elem_nil")
def DEF_ELEM_CONS(x, xs, y, ys):
    return Thm(Elem(Cons(x, xs), Cons(y, ys)), Cons(Sub(x, y), Elem(xs, ys)), "def_elem_cons")
def DEF_SUB(a, b):            return Thm(Sub(a, b), Add(a, Sub(Zero(), b)), "def_sub")

# --- abelian-group axioms for (R, +, 0, -) -----------------------------------
def AX_ASSOC(a, b, c):        return Thm(Add(Add(a, b), c), Add(a, Add(b, c)), "ax_assoc")
def AX_COMM(a, b):            return Thm(Add(a, b), Add(b, a), "ax_comm")
def AX_ZERO(a):               return Thm(Add(a, Zero()), a, "ax_zero")
def AX_NEG(a):                return Thm(Add(a, Sub(Zero(), a)), Zero(), "ax_neg")

# --- hypothesis introduction --------------------------------------------------
def ASSUME(l, r):             return Thm(l, r, "assume", frozenset({Eq(l, r)}))

# --- decision rule for the theory of abelian groups (sound + complete) --------
def _norm(t):
    if isinstance(t, Zero):
        return {}
    if isinstance(t, Add):
        d = dict(_norm(t.a))
        for k, v in _norm(t.b).items():
            d[k] = d.get(k, 0) + v
        return d
    if isinstance(t, Sub):
        d = dict(_norm(t.a))
        for k, v in _norm(t.b).items():
            d[k] = d.get(k, 0) - v
        return d
    return {t: 1}                                  # any other term = generator

def ABGRP(l, r):
    clean = lambda d: {k: v for k, v in d.items() if v != 0}
    nl, nr = clean(_norm(l)), clean(_norm(r))
    if nl != nr:
        raise RuleError("ABGRP: %s vs %s" % (nl, nr))
    return Thm(l, r, "abgrp")

# --- datatype induction for the pair of vectors ------------------------------
def INDUCT(base, step):
    if base.hyps:
        raise RuleError("INDUCT: base case must be closed")
    if not (isinstance(base.l, Sum) and isinstance(base.l.v, Elem)
            and base.l.v.a == Nil() and base.l.v.b == Nil()
            and base.r == Sub(Sum(Nil()), Sum(Nil()))):
        raise RuleError("INDUCT: bad base case")
    c = step.l
    if not (isinstance(c, Sum) and isinstance(c.v, Elem)
            and isinstance(c.v.a, Cons) and isinstance(c.v.b, Cons)):
        raise RuleError("INDUCT: bad step shape")
    x, xs = c.v.a.h, c.v.a.t
    y, ys = c.v.b.h, c.v.b.t
    if step.r != Sub(Sum(Cons(x, xs)), Sum(Cons(y, ys))):
        raise RuleError("INDUCT: step conclusion does not match")
    ih = Eq(Sum(Elem(xs, ys)), Sub(Sum(xs), Sum(ys)))
    if ih not in step.hyps:
        raise RuleError("INDUCT: induction hypothesis not assumed")
    claim = Claim("forall a b : vector(R), len(a) = len(b) => "
                  "sum(eltsub(a,b)) = sum(a) - sum(b)")
    return Thm(claim, claim, "induct")

# ============================ 3. THE PROOF ====================================
x, y, xs, ys = Var("x"), Var("y"), Var("xs"), Var("ys")

# ---- base case:  sum(eltsub(nil,nil)) = sum(nil) - sum(nil) ----
base_l = TRANS(SUM_CONG(DEF_ELEM_NIL()), DEF_SUM_NIL())      # sum(E(nil,nil)) = 0
rhs_l  = SUB_CONG(DEF_SUM_NIL(), DEF_SUM_NIL())              # sum(nil)-sum(nil) = 0-0
base   = TRANS(base_l, TRANS(ABGRP(Zero(), Sub(Zero(), Zero())), SYM(rhs_l)))

# ---- step case (IH = induction hypothesis) ----
IH    = ASSUME(Sum(Elem(xs, ys)), Sub(Sum(xs), Sum(ys)))
lhs_l = Sum(Elem(Cons(x, xs), Cons(y, ys)))
lhs_m = Sum(Cons(Sub(x, y), Elem(xs, ys)))
lhs_n = Add(Sub(x, y), Sum(Elem(xs, ys)))
lhs_o = Add(Sub(x, y), Sub(Sum(xs), Sum(ys)))

h1 = SUM_CONG(DEF_ELEM_CONS(x, xs, y, ys))          # lhs_l = lhs_m
h2 = DEF_SUM_CONS(Sub(x, y), Elem(xs, ys))          # lhs_m = lhs_n
h3 = ADD_CONG(REFL(Sub(x, y)), IH)                  # lhs_n = lhs_o
lhs_chain = TRANS(TRANS(h1, h2), h3)

rhs_l = Sub(Sum(Cons(x, xs)), Sum(Cons(y, ys)))
rhs_m = Sub(Add(x, Sum(xs)), Add(y, Sum(ys)))
rhs_chain = SUB_CONG(DEF_SUM_CONS(x, xs), DEF_SUM_CONS(y, ys))   # rhs_l = rhs_m

leaf = ABGRP(lhs_o, rhs_m)                          # group identity
step = TRANS(lhs_chain, TRANS(leaf, SYM(rhs_chain)))

final = INDUCT(base, step)

# ============================ 4. REPORT =======================================
print("--- kernel report ---")
print("base  :", base)
print("step  :", step)
print("final :", final)
print()
